    private static Resource? ResourceValue(Variant value)=>value.VariantType==Variant.Type.Object?value.AsGodotObject() as Resource:null;
    private readonly ActorPropertyOperations _properties=new();private readonly ActorDataOperations _data=new();private readonly ActorAnimationOperations _animation=new();
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;private static GDScript Script()=>GD.Load<GDScript>("res://scripts/actors/physics/powder/powder_material.gd");private static GArray Constants(string name)=>Script().GetScriptConstantMap()[name].AsGodotArray();private static Settings Values(Resource resource)=>resource.Get("values").AsGodotDictionary();
    public GArray fields(){var result=new GArray();foreach(var value in Constants("FIELD_ROWS")){var row=value.AsGodotArray();var hints=row[3].AsGodotDictionary();var property=_properties.create(new StringName(row[0].AsString()),row[1].AsString(),row[2],!Get(hints,"no_keyframes",false).AsBool());var options=property.Get("options").AsGodotDictionary();options.Merge(hints);options["group"]="Appearance";result.Add(property);}var keys=new[]{"powder_custom_mesh","powder_custom_mesh_2","powder_custom_mesh_3"};var titles=new[]{"Custom grain mesh","Alternate mesh 2","Alternate mesh 3"};for(int i=0;i<keys.Length;i++){var property=_properties.create(new StringName(keys[i]),titles[i],"",true);property.Get("options").AsGodotDictionary().Merge(new Settings{["group"]="Geometry",["file_picker"]=true,["extensions"]=new GArray{"tres","res","mesh"},["native_resource_types"]=new GArray{"Mesh"},["file_resource_mode"]="uneditable",["visible_when"]=new Settings{["property"]="powder_grain_shape",["values"]=new GArray{4}}});result.Add(property);}keys=new[]{"powder_texture","powder_normal","powder_roughness_texture","powder_surface_material"};titles=new[]{"Albedo texture","Normal / detail texture","Roughness texture","Surface material override"};for(int i=0;i<keys.Length;i++){bool material=i==3;var property=_properties.create(new StringName(keys[i]),titles[i],default,true);property.Set("object_type",new StringName(material?"material":"image"));property.Get("options").AsGodotDictionary().Merge(new Settings{["group"]=material?"Appearance":"Textures",["accepted_object_types"]=material?new GArray{"material","shader_material","natural_material"}:new GArray{"image","noise_image"}});result.Add(property);}return result;}
    public Resource definition(){var definition=new ActorObjectDefinition();definition.Set("type_id",new StringName("powder_material"));definition.Set("display_name","Powder Material");var properties=definition.Get("properties").AsGodotArray();foreach(var row in new[]{new[]{"material_name","Name","Sand"},new[]{"material_id","Material ID",""},new[]{"preset_origin","Original preset","Sand"}}){var property=_properties.create(new StringName(row[0]),row[1],row[2],true);var options=property.Get("options").AsGodotDictionary();options["group"]="Material";options["no_keyframes"]=true;properties.Add(property);}foreach(var property in fields())properties.Add(property);var physical=Constants("PHYSICS");var transport=Constants("TRANSPORT");var actorDefinition=GD.Load<GDScript>("res://scripts/actors/physics/powder/powder_definition.gd").Call("create").As<Resource>();foreach(var value in actorDefinition.Get("properties").AsGodotArray()){var property=value.As<Resource>();string key=property.Get("id").AsString();if(!physical.Contains(key)&&!transport.Contains(key))continue;var copy=property.Duplicate(true);var options=copy.Get("options").AsGodotDictionary();options["group"]="Physics defaults — apply to adopt";options.Remove("visible_when");options.Remove("advanced");options["no_keyframes"]=true;properties.Add(copy);}return definition;}
    public Resource preset(int index){index=Math.Clamp(index,0,6);var data=new ActorObjectData();data.Set("type_id",new StringName("powder_material"));var values=Values(data);foreach(var value in fields()){var property=value.As<Resource>();values[property.Get("id")]=_properties.create_default(property);}var names=Constants("NAMES");values[new StringName("material_name")]=names[index];values[new StringName("material_id")]=_data.new_id();values[new StringName("preset_origin")]=names[index];values[new StringName("powder_color")]=new Color(new[]{"c4a069","e4f1ff","60402b","666c70","a3998b","f5f8ff","f6edcf"}[index]);values[new StringName("powder_secondary")]=new Color(new[]{"eed6a0","ffffff","a58756","b7afa0","c3b6a1","cbd9e9","ffffff"}[index]);values[new StringName("powder_grain_shape")]=new[]{1,3,2,2,0,3,3}[index];string[] keys={"powder_shape_variation","powder_color_variation","powder_roughness","powder_specular","powder_detail_intensity","powder_radius","powder_size_variation","powder_density","powder_friction","powder_cohesion","powder_flowability","powder_restitution","powder_compaction","powder_wind","powder_air_drag"};double[][] recipes={new[]{.25,.6,.85,.65,.2,.12,.4},new[]{.4,.25,.7,.8,.25,.3,.25},new[]{.85,.38,.97,.9,1,.2,.3},new[]{.4,.8,.15,.4,.1,.9,.8},new[]{.3,.08,.65,.45,.05,.05,.1},new[]{.055,.07,.065,.11,.022,.045,.05},new[]{.2,.3,.45,.5,.25,.15,.25},new[]{1600.0,350,1350,2600,300,2160,1580},new[]{.6,.8,.85,1.1,.4,.4,.45},new[]{0.0,.08,.035,0,.001,0,.002},new[]{.65,.2,.35,.2,.8,.85,.75},new[]{.03,.01,.02,.12,.01,.12,.08},new[]{.97,.65,.85,.99,.7,.98,.97},new[]{1.0,2,.8,.15,5,.7,.8},new[]{.47,.8,.65,.4,1.2,.5,.55}};for(int i=0;i<keys.Length;i++)values[new StringName(keys[i])]=recipes[i][index];values[new StringName("powder_damping")]=.08;values[new StringName("powder_gravity")]=1.0;values[new StringName("powder_advanced_material")]=false;return data;}
    public Settings appearance(Settings values){var result=values.Duplicate();var reference=ResourceValue(Get(values,"powder_material"));if(Get(values,"powder_link_appearance",false).AsBool()&&ActorDataOperations.ScriptIs(reference,"res://scripts/actors/core/actor_object_reference.gd")){var data=_animation.resolve_reference(reference!);if(data!=null)foreach(var value in Constants("VISUAL")){string key=value.AsString();if(Values(data).TryGetValue(new StringName(key),out var item))result[new StringName(key)]=item;}}return result;}
    public Resource capture(Resource actor){var data=preset(0);var values=appearance(Values(actor));Values(data)[new StringName("material_name")]=actor.Get("display_name").AsString()+" material";Values(data)[new StringName("preset_origin")]="Custom";foreach(string group in new[]{"VISUAL","PHYSICS","TRANSPORT"})foreach(var item in Constants(group)){string key=item.AsString();if(values.TryGetValue(new StringName(key),out var value))Values(data)[new StringName(key)]=_data.copy_value(value);}return data;}
    private static void History(RefCounted model,GArray before,GArray after,string name){var history=model.Get("history").As<UndoRedo>();var action=new PowderSettingsHistoryAction(model,before,after);history.CreateAction(name);history.AddDoMethod(new Callable(action,nameof(PowderSettingsHistoryAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(PowderSettingsHistoryAction.restore_before)));history.AddDoReference(action);history.CommitAction();}
    public void apply(RefCounted model,GArray actors,Resource? reference,int mode){var data=reference!=null?_animation.resolve_reference(reference):null;var before=new GArray();var after=new GArray();foreach(var item in actors){var actor=item.As<Resource>();if(actor.Get("type_id").AsString()!="powder")continue;before.Add(new Settings{["actor"]=actor,["values"]=Values(actor).Duplicate(true)});var values=Values(actor).Duplicate(true);if(mode!=2){values[new StringName("powder_material")]=reference!=null?Variant.From(_data.copy_reference(reference)):default;values[new StringName("powder_link_appearance")]=data!=null;if(data!=null)foreach(var field in Constants("VISUAL")){var key=new StringName(field.AsString());if(Values(data).TryGetValue(key,out var value))values[key]=_data.copy_value(value);}}if(mode!=1&&data!=null){foreach(string group in new[]{"PHYSICS","TRANSPORT"})foreach(var field in Constants(group)){var key=new StringName(field.AsString());if(Values(data).TryGetValue(key,out var value))values[key]=value;}values[new StringName("powder_spacing")]=Math.Max(values["powder_spacing"].AsDouble(),values["powder_radius"].AsDouble()*2*(1+values["powder_size_variation"].AsDouble())*1.08);}after.Add(new Settings{["actor"]=actor,["values"]=values});}History(model,before,after,"Powder material: "+new[]{"appearance + physics","appearance only","physics only"}[mode]);}
    public void link(RefCounted model,GArray actors,bool enabled){var before=new GArray();var after=new GArray();foreach(var item in actors){var actor=item.As<Resource>();before.Add(new Settings{["actor"]=actor,["values"]=Values(actor).Duplicate(true)});var values=Values(actor).Duplicate(true);if(!enabled){var current=appearance(Values(actor));foreach(var field in Constants("VISUAL")){var key=new StringName(field.AsString());if(current.TryGetValue(key,out var value))values[key]=_data.copy_value(value);}}values[new StringName("powder_link_appearance")]=enabled&&Get(values,"powder_material").VariantType!=Variant.Type.Nil;after.Add(new Settings{["actor"]=actor,["values"]=values});}History(model,before,after,"Powder material appearance link");}
    public bool physical_path(string[] path)=>path.Length>0&&!Constants("VISUAL").Contains(path[0])&&path[0] is not ("powder_material" or "powder_link_appearance" or "powder_preset" or "powder_show_source");
